const stor = (s) => s.charAt(0).toUpperCase() + s.slice(1);
// Oversett et navn som står med liten forbokstav inne i en setning
const smaa = (o, s) => { const x = o(stor(s)); return x === stor(s) ? s : x.toLowerCase(); };
const bare = (o, s) => { const x = o(s); return x !== s ? x : null; }; // bare hvis det faktisk finnes en oversettelse

export const MONSTRE = [
  // Grunner til middagsforslag
  [/^(.+) på tilbud hos (.+?) \((\d+) % billigere\)$/, (m, o) => `${o(m[1])} on offer at ${m[2]} (${m[3]} % cheaper)`],
  [/^(.+) på tilbud hos (.+)$/, (m, o) => `${o(m[1])} on offer at ${m[2]}`],
  [/^Dere har (.+) og (.+) hjemme$/, (m, o) => `You have ${smaa(o, m[1])} and ${smaa(o, m[2])} at home`],
  // Tilbud
  [/^(\d+) % under vanlig \(~(.+) kr\/(kg|l|stk)\)$/, (m) => `${m[1]} % below usual (~${m[2]} kr/${m[3] === 'stk' ? 'pc' : m[3]})`],
  [/^−(\d+) % \(før (.+) kr\)$/, (m) => `−${m[1]} % (was ${m[2]} kr)`],
  // Knapper og lister med navn i
  [/^Bytt middag (.+)$/, (m, o) => `Change dinner ${o(m[1]).toLowerCase()}`],
  [/^Beløp per måned for (.+)$/, (m, o) => `Amount per month for ${o(m[1])}`],
  [/^Fjern (.+)$/, (m, o) => `Remove ${o(m[1])}`],
  [/^Endre (.+)$/, (m, o) => `Edit ${o(m[1])}`],
  [/^Mindre (.+)$/, (m, o) => `Less ${o(m[1])}`],
  [/^Mer (.+)$/, (m, o) => `More ${o(m[1])}`],
  [/^(.+) er tom$/, (m, o) => `${o(m[1])} is empty`],
  [/^(.+) – ([^–]+)$/, (m, o) => (bare(o, m[1]) ? `${o(m[1])} – ${m[2]}` : null)],
  [/^(.+) \(([^()]+)\)$/, (m, o) => (bare(o, m[1]) ? `${o(m[1])} (${m[2]})` : null)],
  [/^(.+): (\d[\d\s,.]*) kr$/, (m, o) => (bare(o, m[1]) ? `${o(m[1])}: ${m[2]} kr` : null)],
  [/^Fordeling: (.+)$/, (m, o) => `Breakdown: ${m[1].split(', ').map((d) => { const x = d.match(/^(.+) (\d[\d\s,.]*) kr$/); return x ? `${o(x[1])} ${x[2]} kr` : d; }).join(', ')}`],
  // Retter og måltider i lister («Taco, Frokost»)
  [/^[^,]+(, [^,]+)+( …)?$/, (m, o) => { const deler = m[0].replace(/ …$/, '').split(', '); const ut = deler.map(o); return ut.every((x, i) => x !== deler[i]) ? ut.join(', ') + (m[2] || '') : null; }],
];
